package ext

import (
	\"bytes\"
	\"context\"
	\"encoding/json\"
	\"strings\"
	\"testing\"

	flipt \"github.com/markphelps/flipt/rpc/flipt\"
	\"github.com/markphelps/flipt/storage\"
	\"gopkg.in/yaml.v2\"
)

type testLister struct{}

func (testLister) ListFlags(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Flag, error) {
	params := &storage.QueryParams{}
	for _, opt := range opts { opt(params) }
	if params.Offset > 0 { return nil, nil }
	return []*flipt.Flag{{Key: \"flag\", Name: \"Flag\", Enabled: true, Variants: []*flipt.Variant{
		{Id: \"variant-id\", Key: \"complex\", Attachment: "'`{"array":[1,true,null,{"nested":["text",2.5]}],"empty":{}}`},
		{Id: "other-id", Key: "empty"},
	}}}, nil
}
func (testLister) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule, error) {
	return []*flipt.Rule{{Id: "rule-id", SegmentKey: "segment", Rank: 1, Distributions: []*flipt.Distribution{{VariantId: "variant-id", Rollout: 100}}}}, nil
}
func (testLister) ListSegments(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Segment, error) {
	params := &storage.QueryParams{}
	for _, opt := range opts { opt(params) }
	if params.Offset > 0 { return nil, nil }
	return []*flipt.Segment{{Key: "segment", MatchType: flipt.MatchType_ANY_MATCH_TYPE, Constraints: []*flipt.Constraint{{Type: flipt.ComparisonType_STRING_COMPARISON_TYPE, Property: "region", Operator: "eq", Value: "west"}}}}, nil
}

type testCreator struct { variants []*flipt.CreateVariantRequest; flags int; segments int; constraints int; rules int; distributions int }
func (s *testCreator) CreateFlag(_ context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) { s.flags++; return &flipt.Flag{Key: r.Key}, nil }
func (s *testCreator) CreateVariant(_ context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) { s.variants = append(s.variants, r); return &flipt.Variant{Id: r.Key + "-id", Key: r.Key}, nil }
func (s *testCreator) CreateSegment(_ context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error) { s.segments++; return &flipt.Segment{Key: r.Key}, nil }
func (s *testCreator) CreateConstraint(_ context.Context, _ *flipt.CreateConstraintRequest) (*flipt.Constraint, error) { s.constraints++; return &flipt.Constraint{}, nil }
func (s *testCreator) CreateRule(_ context.Context, _ *flipt.CreateRuleRequest) (*flipt.Rule, error) { s.rules++; return &flipt.Rule{Id: "rule-id"}, nil }
func (s *testCreator) CreateDistribution(_ context.Context, _ *flipt.CreateDistributionRequest) (*flipt.Distribution, error) { s.distributions++; return &flipt.Distribution{}, nil }

func TestExportImportAttachments(t *testing.T) {
	ctx := context.Background()
	var out bytes.Buffer
	if err := NewExporter(testLister{}).Export(ctx, &out); err != nil { t.Fatal(err) }
	var doc Document
	if err := yaml.Unmarshal(out.Bytes(), &doc); err != nil { t.Fatal(err) }
	if len(doc.Flags) != 1 || len(doc.Flags[0].Variants) != 2 || len(doc.Segments) != 1 || doc.Segments[0].MatchType != "ANY_MATCH_TYPE" { t.Fatalf("incomplete export: %s", out.String()) }
	if doc.Flags[0].Variants[1].Attachment != nil { t.Fatalf("empty attachment exported: %s", out.String()) }
	if strings.Contains(out.String(), `attachment: '"'{"'`) { t.Fatalf("attachment was quoted JSON: %s", out.String()) }

	creator := &testCreator{}
	if err := NewImporter(creator).Import(ctx, &out); err != nil { t.Fatal(err) }
	if creator.flags != 1 || creator.segments != 1 || creator.constraints != 1 || creator.rules != 1 || creator.distributions != 1 || len(creator.variants) != 2 { t.Fatalf("incomplete import: %+v", creator) }
	if creator.variants[1].Attachment != "" { t.Fatalf("missing attachment became %q", creator.variants[1].Attachment) }
	var attachment interface{}
	if err := json.Unmarshal([]byte(creator.variants[0].Attachment), &attachment); err != nil { t.Fatal(err) }
	value := attachment.(map[string]interface{})["array"].([]interface{})
	if len(value) != 4 || value[2] != nil || value[3].(map[string]interface{})["nested"].([]interface{})[0] != "text" { t.Fatalf("attachment changed: %#v", attachment) }
}

func TestImportYAMLMapKeysAndNoAttachment(t *testing.T) {
	creator := &testCreator{}
	input := `flags:
- key: flag
  enabled: true
  variants:
  - key: with-map
    attachment:
      7:
      - false
      - null
  - key: absent
segments:
- key: segment
`
	if err := NewImporter(creator).Import(context.Background(), strings.NewReader(input)); err != nil { t.Fatal(err) }
	if creator.variants[0].Attachment != `{"7":[false,null]}` || creator.variants[1].Attachment != "" { t.Fatalf("attachments: %+v", creator.variants) }
}
EOF
